public static class WaterSportsAuthoring {
 public const string Folder="TruckWaterSports";
 public const string PaddleScene="Assets/TruckWaterSports/Scenes/PaddlePals.unity",KayakScene="Assets/TruckWaterSports/Scenes/WhitewaterWipeout.unity",BlackwaterScene="Assets/TruckWaterSports/Scenes/Blackwater.unity";
 [MenuItem("Truck Sports/Alpha 0.10/Create water sports (new scenes only)")]public static void CreateAll(){CreatePaddlePals();CreateWhitewaterWipeout();CreateBlackwater();}
