 static void Create<T>(string scene,bool canoe,bool lake)where T:WaterMatch {
 if(File.Exists(scene)){Debug.Log("WATER_PRESERVE_AUTHORED "+scene);return;}
 Directory.CreateDirectory("Assets/"+Folder+"/Art");Directory.CreateDirectory("Assets/"+Folder+"/Scenes");var m=SportsEventAuthoring.Begin<T>(Folder);var venueSky=new Material(RenderSettings.skybox);AssetDatabase.CreateAsset(venueSky,"Assets/"+Folder+"/Materials/"+typeof(T).Name+" sky.mat");RenderSettings.skybox=venueSky;m.setup.count=4;m.option=0;m.matchDuration=lake?240:180;m.NormalizeSetup();for(int i=1;i<4;i++)m.setup.players[i].source=LWS.TruckBowling.BowlingSource.AI;
 var course=m.gameObject.AddComponent<WaterCourse>();m.course=course;course.lake=lake;course.width=lake?240:canoe?38:29;course.currentSpeed=lake?0:canoe?5:8;course.turbulence=canoe?.35f:1.3f;
 var points=new List<Vector3>();if(lake){points.Add(new Vector3(0,0,0));points.Add(new Vector3(-45,0,90));points.Add(new Vector3(65,0,170));points.Add(new Vector3(-60,0,245));points.Add(new Vector3(0,0,315));}else for(int i=0;i<19;i++){float y=26-i*.7f-(i>8?8:0)-(i>14?12:0);if(i==9||i==15){var lip=points[points.Count-1];points.Add(new Vector3(lip.x,lip.y,lip.z+19));points.Add(new Vector3(lip.x,y,lip.z+20));}points.Add(new Vector3(Mathf.Sin(i*.55f)*32,y,i*42));}course.stations=points.ToArray();if(!canoe&&!lake)course.eddies=new[]{points[6]+Vector3.right*7,points[11]-Vector3.right*8};
 var wood=SportsEventAuthoring.Mat(Folder,"River cedar and oiled gunwales",new Color(.48f,.24f,.095f),.35f);wood.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/RoadPropsPack/Textures/T_WoodBox_AlbedoTransparency.png");var foam=SportsEventAuthoring.Mat(Folder,"Water gate enamel",new Color(.96f,.83f,.25f),.4f);var bed=SportsEventAuthoring.Mat(Folder,"Riverbed earth",new Color(.24f,.3f,.2f),.04f);var contact=SportsEventAuthoring.Contact(Folder,"Rock and timber contact",.45f,.1f);var waterSource=AssetDatabase.LoadAssetAtPath<Material>("Assets/RiverModeler/ShaderGraph/Default River.mat");if(waterSource==null)throw new InvalidOperationException("Owned RiverModeler material missing.");
 var water=new Material(waterSource);water.SetFloat("_Animation_Speed",lake?.12f:1);water.SetColor("_BaseColor",lake?new Color(.025f,.07f,.09f):new Color(.12f,.38f,.5f));AssetDatabase.CreateAsset(water,"Assets/"+Folder+"/Materials/"+typeof(T).Name+" river surface.mat");
 var terrainLayer=AssetDatabase.LoadAssetAtPath<TerrainLayer>("Assets/3D Haven/Path Painter II/Editor/Demo/Terrains/DocsTerrain/TerrainLayers/stdMudRocky.terrainlayer");if(terrainLayer!=null){bed.mainTexture=terrainLayer.diffuseTexture;bed.mainTextureScale=Vector2.one*8;}Surface(course,water,lake);Terrain(course,wood,bed,contact,lake);Forest(course,lake);Gates(course,foam,wood,lake);
 m.vessels=new WaterVessel[canoe?2:4];for(int i=0;i<m.vessels.Length;i++)m.vessels[i]=Boat(m,i,canoe,lake,wood,contact);
 m.broadcast=SportsEventAuthoring.Camera("River action broadcast");m.broadcast.view.farClipPlane=1800;m.participantCameras=new SportsEventCamera[4];var cameras=new List<Camera>{m.broadcast.view};for(int i=0;i<4;i++){m.participantCameras[i]=SportsEventAuthoring.Camera("Owned watercraft camera "+i);m.participantCameras[i].view.enabled=false;m.participantCameras[i].view.farClipPlane=1500;cameras.Add(m.participantCameras[i].view);}m.cameras=cameras.ToArray();m.broadcast.Pose(points[0]+Vector3.forward*15,new Vector3(35,28,-40),62,true);
 m.feedback.clips=new AudioClip[7];m.feedback.clips[0]=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/WeatherMaker/Prefab/Sound/Water/WeatherMakerWaterSound_Splash.ogg");var river=m.gameObject.AddComponent<AudioSource>();river.clip=AssetDatabase.LoadAssetAtPath<AudioClip>(lake?"Assets/WeatherMaker/Prefab/Sound/Water/WeatherMakerWaterSound_Underwater.ogg":"Assets/RiverModeler/SFX/Shallow Creek Fast.wav");river.loop=true;river.playOnAwake=false;river.volume=.13f;var ownedAudio=m.gameObject.AddComponent<WaterAudio>();ownedAudio.match=m;ownedAudio.ambience=river;
 if(lake)Night((BlackwaterMatch)(WaterMatch)m,wood,contact);else{m.presentationWeather=SportsChaosAuthoring.Weather(m,Folder);SportsWeatherRenderingAuthoring.Install(m,Folder);}
 SportsEventAuthoring.UI(m);SportsRallyAuthoring.CompactUI(m);EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),scene);SportsProductionAuthoring.InstallScene();SportsFocusPolicy.InstallScene();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),scene);AssetDatabase.SaveAssets();Debug.Log("ALPHA10_WATER_AUTHORED "+scene+" actual Archimeds hulls/paddle impulses/current gates");
 }
 static WaterVessel Boat(WaterMatch m,int index,bool canoe,bool lake,Material wood,PhysicsMaterial contact){var root=new GameObject(lake?"Truck-bearing rescue barge":canoe?"Two-station cedar canoe":"Individual whitewater kayak");root.transform.position=m.course.Point(0)+new Vector3((index-(canoe?.5f:1.5f))*(canoe?10:6),.1f,0);var body=root.AddComponent<Rigidbody>();body.mass=canoe?2000:lake?1800:900;body.linearDamping=.18f;body.angularDamping=.8f;body.centerOfMass=new Vector3(0,-.4f,0);body.interpolation=RigidbodyInterpolation.Interpolate;body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;body.solverIterations=16;
 var boat=root.AddComponent<WaterVessel>();boat.body=body;boat.course=m.course;boat.firstSlot=canoe?index*2:index;boat.secondSlot=canoe?index*2+1:-1;boat.strokeImpulse=canoe?1.8f:2.3f;
 float length=canoe?13:lake?9:6,width=canoe?3.6f:lake?5.5f:2.8f;var model=new GameObject("Crafted sealed hull",typeof(MeshFilter),typeof(MeshRenderer));model.transform.SetParent(root.transform,false);model.GetComponent<MeshFilter>().sharedMesh=Hull("Hull "+(canoe?"canoe":lake?"barge":"kayak"),width,length);model.GetComponent<MeshRenderer>().sharedMaterial=wood;
 var collider=root.AddComponent<BoxCollider>();collider.size=new Vector3(width,.65f,length*.82f);collider.center=new Vector3(0,-.3f,0);collider.sharedMaterial=contact;
 var floating=root.AddComponent<SportsFloatingBody>();floating.body=body;floating.session=m;floating.proxy=VesselProxy(canoe?"Canoe":lake?"Barge":"Kayak",body.mass);floating.waterHeight=m.course.Point(0).y;floating.waveAmplitude=lake?.1f:.06f;boat.flotation=floating;
 for(int seat=0;seat<(canoe?2:1);seat++){int slot=canoe?index*2+seat:index;var station=new GameObject("Seated participant truck "+slot).transform;station.SetParent(root.transform,false);station.localPosition=new Vector3(0,.7f,canoe?(seat==0?-2.8f:2.8f):0);var truck=LWS.TruckHockey.Editor.HockeyAuthoring.TruckGeometry(station,2.6f);truck.name="Boat-mounted tractor visual";CenterSeatedVisual(truck.transform,station);var paints=truck.GetComponentsInChildren<Renderer>().Where(r=>r.name=="Cab").ToArray();if(seat==0)boat.firstPaint=paints;else boat.secondPaint=paints;foreach(var c in truck.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(c);}
 boat.paddles=new Transform[2];for(int side=0;side<2;side++){var pivot=new GameObject("Working paddle station "+side).transform;pivot.SetParent(root.transform,false);pivot.localPosition=new Vector3((side==0?-1:1)*width*.5f,.6f,canoe?(side==0?-2.8f:2.8f):0);var shaft=SportsEventAuthoring.Box("Oar shaft",new Vector3(0,-.6f,0),new Vector3(.13f,2.7f,.13f),wood,null,pivot);var blade=SportsEventAuthoring.Box("Broad paddle blade",new Vector3(0,-2,0),new Vector3(.65f,.95f,.12f),wood,null,pivot);boat.paddles[side]=pivot;}
 if(lake)for(int side=-1;side<=1;side+=2){var lamp=new GameObject("Barge navigation headlight").AddComponent<Light>();lamp.transform.SetParent(root.transform,false);lamp.transform.localPosition=new Vector3(side*1.3f,1.4f,length*.35f);lamp.type=LightType.Spot;lamp.range=70;lamp.spotAngle=62;lamp.intensity=30;lamp.color=new Color(.8f,.9f,1);}boat.Capture();body.isKinematic=true;return boat;}
 // The vessel rigidbody is the lumped hull-and-payload mass. Its sealed
 // displacement compartment sits below the visible deck; Archimeds retains
 // all buoyancy/drag forces. Cargo supplies keep their separate original proxy.
 static Mesh VesselProxy(string kind,float mass)=>Proxy(kind+" payload displacement "+mass.ToString("F0"),mass*2.1f,-.15f);
 static Mesh Proxy(string name,float displacedMass,float centerY=0){string path="Assets/"+Folder+"/Art/"+name+" hydrostatic closed proxy.asset";var found=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(found!=null)return found;var primitive=GameObject.CreatePrimitive(PrimitiveType.Cube);var mesh=UnityEngine.Object.Instantiate(primitive.GetComponent<MeshFilter>().sharedMesh);UnityEngine.Object.DestroyImmediate(primitive);var vertices=mesh.vertices;float s=Mathf.Pow(displacedMass/1000,1f/3);for(int i=0;i<vertices.Length;i++)vertices[i]=Vector3.Scale(vertices[i],new Vector3(s*.65f,s*.65f,s/ (.65f*.65f)))+Vector3.up*centerY;mesh.vertices=vertices;mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,path);return mesh;}
 static void CenterSeatedVisual(Transform visual,Transform station){Bounds bounds=default;bool first=true;foreach(var filter in visual.GetComponentsInChildren<MeshFilter>(true)){if(filter.sharedMesh==null)continue;var part=SportsRallyAuthoring.BoundsIn(filter,station);if(first){bounds=part;first=false;}else bounds.Encapsulate(part);}if(first)throw new InvalidOperationException("Seated truck requires its authored model meshes.");visual.localPosition-=new Vector3(bounds.center.x,bounds.min.y,bounds.center.z);}
 [MenuItem("Truck Sports/Alpha 0.10/Repair active water payload attachment")]
 public static void RepairActiveVesselPayloads(){
  if(Application.isPlaying)throw new InvalidOperationException("Repair the saved water scene outside Play Mode.");
  var match=UnityEngine.Object.FindAnyObjectByType<WaterMatch>();if(match==null)throw new InvalidOperationException("Open a water sport scene before repairing payloads.");int repaired=0;
  foreach(var vessel in match.vessels){if(vessel==null)continue;var seats=new List<Transform>();foreach(Transform child in vessel.transform)if(child.name.StartsWith("Seated participant truck ",StringComparison.Ordinal))seats.Add(child);
   foreach(var current in seats){var visual=current.Find("Boat-mounted tractor visual");Transform station=current;
    if(visual==null){var pose=current.localPosition;var rotation=current.localRotation;string label=current.name;current.name="Boat-mounted tractor visual";station=new GameObject(label).transform;station.SetParent(vessel.transform,false);station.localPosition=pose;station.localRotation=rotation;current.SetParent(station,false);current.localRotation=Quaternion.identity;visual=current;}
    var position=station.localPosition;if(Mathf.Abs(position.y-.55f)<.001f)position.y=.7f;station.localPosition=position;CenterSeatedVisual(visual,station);EditorUtility.SetDirty(station);repaired++;
   }
   if(vessel.flotation!=null&&vessel.flotation.proxy!=null){string kind=match is PaddlePalsMatch?"Canoe":match is BlackwaterMatch?"Barge":"Kayak";if(vessel.flotation.proxy.name==kind+" hydrostatic closed proxy"){vessel.flotation.proxy=VesselProxy(kind,vessel.body.mass);EditorUtility.SetDirty(vessel.flotation);}}
   EditorUtility.SetDirty(vessel);
  }
  EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());AssetDatabase.SaveAssets();Debug.Log("WATER_PAYLOAD_REPAIRED "+match.Title+" stations="+repaired+"; original model meshes/materials preserved; one vessel physics body");
 }
 static Mesh Hull(string name,float width,float length){string path="Assets/"+Folder+"/Art/"+name+".asset";var found=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(found!=null)return found;var v=new List<Vector3>();var t=new List<int>();const int rings=25,sides=18;for(int z=0;z<rings;z++){float along=(float)z/(rings-1);float taper=Mathf.Max(.04f,Mathf.Sin(along*Mathf.PI));for(int side=0;side<sides;side++){float a=side*Mathf.PI*2/sides;v.Add(new Vector3(Mathf.Cos(a)*width*.5f*taper,Mathf.Sin(a)*.65f,(along-.5f)*length));}}for(int z=0;z<rings-1;z++)for(int s=0;s<sides;s++){int a=z*sides+s,b=z*sides+(s+1)%sides,c=a+sides,d=b+sides;t.AddRange(new[]{a,c,b,b,c,d});}var mesh=new Mesh{name=name};mesh.SetVertices(v);mesh.SetUVs(0,v.Select(p=>new Vector2(p.x*.3f,p.z*.3f)).ToList());mesh.SetTriangles(t,0);mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,path);return mesh;}
 static void Surface(WaterCourse c,Material water,bool lake){var g=new GameObject("Owned River Modeler shaded flowing surface",typeof(MeshFilter),typeof(MeshRenderer));var v=new List<Vector3>();var uv=new List<Vector2>();var t=new List<int>();if(lake){const int nx=33,nz=49;for(int z=0;z<nz;z++)for(int x=0;x<nx;x++){v.Add(new Vector3(-150+x*300f/(nx-1),0,-50+z*410f/(nz-1)));uv.Add(new Vector2(x*.5f,z*.5f));if(x<nx-1&&z<nz-1){int a=z*nx+x;t.AddRange(new[]{a,a+nx,a+1,a+1,a+nx,a+nx+1});}}var wake=g.AddComponent<BlackwaterWake>();wake.match=(BlackwaterMatch)c.GetComponent<WaterMatch>();wake.match.wake=wake;}else{for(int i=0;i<c.stations.Length;i++){var forward=(c.Point(i+1)-c.Point(i-1)).normalized;var right=Vector3.Cross(Vector3.up,forward).normalized;v.Add(c.Point(i)-right*c.width*.5f);v.Add(c.Point(i)+right*c.width*.5f);uv.Add(new Vector2(0,i*2));uv.Add(new Vector2(1,i*2));if(i<c.stations.Length-1){int a=i*2;t.AddRange(new[]{a,a+2,a+1,a+1,a+2,a+3});}}}var mesh=new Mesh{name=lake?"Blackwater lake":"Continuous descending river"};mesh.SetVertices(v);mesh.SetUVs(0,uv);mesh.SetTriangles(t,0);mesh.SetColors(v.Select(_=>new Color(0,0,0,lake?.05f:.3f)).ToList());mesh.RecalculateNormals();mesh.RecalculateTangents();AssetDatabase.CreateAsset(mesh,"Assets/"+Folder+"/Art/"+c.GetComponent<WaterMatch>().GetType().Name+" watercourse.asset");g.GetComponent<MeshFilter>().sharedMesh=mesh;g.GetComponent<MeshRenderer>().sharedMaterial=water;}
 static void Terrain(WaterCourse c,Material wood,Material bed,PhysicsMaterial contact,bool lake){var rocks=new[]{"Assets/TruckFishing/Prefabs/River boulder 0.prefab","Assets/TruckFishing/Prefabs/River boulder 1.prefab","Assets/TruckFishing/Prefabs/River boulder 2.prefab"};for(int i=0;i<c.stations.Length;i++){Vector3 point=c.Point(i);for(int side=-1;side<=1;side+=2){var bank=SportsEventAuthoring.Box("Textured riverbank",point+new Vector3(side*(lake?160:c.width*.5f+12),-2,0),new Vector3(lake?30:25,5,50),bed,contact);for(int j=0;j<3;j++){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(rocks[(i+j)%rocks.Length]);if(prefab==null)throw new InvalidOperationException("Owned river rock missing");var rock=(GameObject)PrefabUtility.InstantiatePrefab(prefab);rock.transform.position=point+new Vector3(side*(lake?145:c.width*.5f+3+j*3),.5f,j*11-10);rock.transform.localScale=Vector3.one*(3+j);}}if(!lake&&i>3&&i%3==0){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(rocks[i%3]);var hazard=(GameObject)PrefabUtility.InstantiatePrefab(prefab);hazard.name="Physical slalom boulder";hazard.transform.position=point+new Vector3(i%2==0?-9:9,-.4f,15);hazard.transform.localScale=Vector3.one*2;if(hazard.GetComponentInChildren<Collider>()==null)hazard.AddComponent<BoxCollider>();}}}
 static void Forest(WaterCourse c,bool lake){for(int i=0;i<c.stations.Length;i++)for(int side=-1;side<=1;side+=2)for(int j=0;j<3;j++){var root=new GameObject("Owned riverside tree").transform;root.position=c.Point(i)+new Vector3(side*(lake?165:c.width*.5f+15+j*8),1,j*13-10);LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(root,j%2==0?"Assets/Toon Gas Station/Prefabs/Tree_7A.prefab":"Assets/Toon Gas Station/Prefabs/Tree_6A.prefab",new Vector3(12,18+j*4,12),0,false,Folder);}}
 static void Gates(WaterCourse c,Material paint,Material wood,bool lake){for(int i=1;i<c.stations.Length;i++){Vector3 p=c.Point(i);for(int side=-1;side<=1;side+=2){var buoy=GameObject.CreatePrimitive(PrimitiveType.Sphere);buoy.name="Slalom buoy "+i;buoy.transform.position=p+new Vector3(side*(lake?14:9),.5f,0);buoy.transform.localScale=new Vector3(1.1f,1.6f,1.1f);buoy.GetComponent<Renderer>().sharedMaterial=paint;UnityEngine.Object.DestroyImmediate(buoy.GetComponent<Collider>());if(lake){var light=buoy.AddComponent<Light>();light.color=new Color(.3f,1,.65f);light.range=18;light.intensity=4;}}}}
 static void Night(BlackwaterMatch m,Material wood,PhysicsMaterial contact){RenderSettings.skybox.SetFloat("_Exposure",.12f);RenderSettings.skybox.SetColor("_SkyTint",new Color(.025f,.045f,.085f));RenderSettings.ambientLight=new Color(.035f,.055f,.075f);RenderSettings.fog=true;RenderSettings.fogColor=new Color(.025f,.05f,.06f);RenderSettings.fogDensity=.004f;foreach(var light in UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None))if(light.type==LightType.Directional){light.intensity=.25f;light.color=new Color(.5f,.65f,.85f);}m.dock=new GameObject("Safe shoreline delivery dock").transform;m.dock.position=m.course.Point(0);SportsEventAuthoring.Box("Timbered rescue dock",new Vector3(0,-.2f,-12),new Vector3(30,1,8),wood,contact);m.supplies=new Rigidbody[4];for(int i=0;i<4;i++){var g=SportsEventAuthoring.Box("Physical supply crate "+i,m.course.Point(3)+new Vector3((i-1.5f)*7,.2f,0),new Vector3(1.5f,1.5f,1.5f),wood,contact);var rb=g.AddComponent<Rigidbody>();rb.mass=100;g.AddComponent<BlackwaterSupply>();m.supplies[i]=rb;var floating=g.AddComponent<SportsFloatingBody>();floating.body=rb;floating.proxy=Proxy("Supply",220);floating.session=m;floating.waterHeight=0;}
 var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Layer Lab/3D Characters-Fish/Fish/Prefabs/BlacktipReefShark.prefab");if(source==null)throw new InvalidOperationException("Owned articulated aquatic model missing.");var creature=(GameObject)PrefabUtility.InstantiatePrefab(source);creature.name="Blackwater physical deepwater leviathan";creature.transform.position=new Vector3(0,-5,90);creature.transform.localScale=Vector3.one*12;foreach(var script in creature.GetComponentsInChildren<MonoBehaviour>(true))UnityEngine.Object.DestroyImmediate(script);foreach(var renderer in creature.GetComponentsInChildren<Renderer>()){var materials=renderer.sharedMaterials;for(int j=0;j<materials.Length;j++){if(materials[j]==null)continue;var original=materials[j];string path="Assets/"+Folder+"/Materials/Blackwater "+original.name+".mat";var owned=AssetDatabase.LoadAssetAtPath<Material>(path);if(owned==null){owned=new Material(Shader.Find("Universal Render Pipeline/Lit"));owned.mainTexture=original.mainTexture;owned.color=original.HasProperty("_Color")?original.color:Color.gray;AssetDatabase.CreateAsset(owned,path);}materials[j]=owned;}renderer.sharedMaterials=materials;}foreach(var collider in creature.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(collider);m.entity=creature.AddComponent<Rigidbody>();m.entity.isKinematic=true;m.wake.entity=m.entity;var shape=creature.AddComponent<BoxCollider>();shape.size=new Vector3(.5f,.4f,2);m.warning=new GameObject("Leviathan positional strike audio").AddComponent<AudioSource>();m.warning.transform.SetParent(m.transform,false);m.warning.playOnAwake=false;m.warning.clip=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/WeatherMaker/Prefab/Sound/Water/WeatherMakerWaterSound_Underwater.ogg");m.warning.spatialBlend=1;m.warning.volume=.6f;
 }
